import type { Food } from "./types";

type SeedFood = Omit<Food, "id">;

/** Compact: name, size, unit, kcal, protein, carbs, fat, fiber, sugar, sodium */
type Row = [string, number, string, number, number, number, number, number, number, number];

const ZERO_MICROS = {
  vitamin_a_mcg: 0,
  vitamin_c_mg: 0,
  vitamin_d_mcg: 0,
  vitamin_b12_mcg: 0,
  iron_mg: 0,
  calcium_mg: 0,
  potassium_mg: 0,
} as const;

function expand(row: Row): SeedFood {
  const [name, serving_size, serving_unit, calories, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg] = row;
  return {
    name,
    serving_size,
    serving_unit,
    calories,
    protein_g,
    carbs_g,
    fat_g,
    fiber_g,
    sugar_g,
    sodium_mg,
    ...ZERO_MICROS,
  };
}

